window.ROUTES=[{"folder":"architecture-map","stops":[{"name":["Конд","Կոնդ"],"description":["Старый район с извилистыми улицами и сложившейся исторической застройкой. Здесь начинается знакомство с разными архитектурными слоями Еревана.","Հին թաղամասի ոլորուն փողոցներն ու պատմական տները բացահայտում են Երևանի ճարտարապետական տարբեր շերտերը։"],"symbol":["История Еревана","Երևանի պատմությունը"],"stage":0,"image":"maps/architecture-map/images/day-1/1-1-kond.jpg"},{"name":["Площадь Республики","Հանրապետության հրապարակ"],"description":["Городской ансамбль, через который маршрут раскрывает монументальную симметрию и столичный масштаб Еревана.","Քաղաքային համալիրը ներկայացնում է Երևանի մոնումենտալ համաչափությունն ու մայրաքաղաքային մասշտաբը։"],"symbol":["История Еревана","Երևանի պատմությունը"],"stage":0,"image":"maps/architecture-map/images/day-1/1-2-republic.jpg"},{"name":["Улица Абовяна","Աբովյան փողոց"],"description":["Остановка на улице Абовяна продолжает знакомство с исторической городской средой и изменением архитектурного облика Еревана.","Պատմական փողոցի միջավայրում ուսումնասիրում ենք քաղաքի ճարտարապետական կերպարի փոփոխությունները։"],"symbol":["История Еревана","Երևանի պատմությունը"],"stage":0,"image":"maps/architecture-map/images/day-1/1-3-abovyan.jpg"},{"name":["Подземный фонтан","Ստորգետնյա շատրվան"],"description":["Фонтан в открытом подземном дворике станции метро «Площадь Республики». Архитектурное пространство раскрывается ниже уровня улицы.","Ստորգետնյա շատրվանը ցույց է տալիս ճարտարապետության, ջրի և հանրային տարածության կապը։"],"symbol":["История Еревана","Երևանի պատմությունը"],"stage":0,"image":"maps/architecture-map/images/day-1/1-4-fontan.jpg"},{"name":["Северный проспект","Հյուսիսային պողոտա"],"description":["Пешеходное пространство в центре города. На маршруте здесь можно сравнить масштаб и характер застройки с историческими кварталами.","Ժամանակակից հետիոտնային պողոտան միացնում է կենտրոնի կարևոր տարածքները։"],"symbol":["История Еревана","Երևանի պատմությունը"],"stage":0,"image":"maps/architecture-map/images/day-1/1-5-north.jpg"},{"name":["Оперный театр","Օպերային թատրոն"],"description":["Один из ключевых городских ансамблей программы. Остановка посвящена монументальной симметрии и роли общественного здания в городе.","Թամանյանի նախագծած թատրոնը քաղաքի ճարտարապետական և մշակութային խորհրդանիշներից է։"],"symbol":["История Еревана","Երևանի պատմությունը"],"stage":0,"image":"maps/architecture-map/images/day-1/1-6-opera.jpg"},{"name":["Скульптурный сад","Քանդակների այգի"],"description":["Открытое пространство у Каскада, где скульптура становится частью городской среды. Через художественные образы маршрут обращается к памяти Еревана.","Բացօթյա քանդակները երկխոսության մեջ են մտնում քաղաքային միջավայրի հետ։"],"symbol":["Память Еревана","Երևանի հիշողությունը"],"stage":1,"image":"maps/architecture-map/images/day-1/1-7-sculptura.jpg"},{"name":["Каскад","Կասկադ"],"description":["Многоуровневый архитектурный ансамбль. Его лестницы, террасы и вертикальная композиция раскрывают связь рельефа, искусства и города.","Աստիճանաշարերը, տեռասներն ու արվեստը միավորում են քաղաքի հիշողությունն ու ժամանակակից կյանքը։"],"symbol":["Память Еревана","Երևանի հիշողությունը"],"stage":1,"image":"maps/architecture-map/images/day-1/1-8-kaskad.jpg"},{"name":["Матенадаран","Մատենադարան"],"description":["Монументальное здание хранилища рукописей. В программе оно представляет сохранение знаний и культурной памяти в архитектуре.","Ձեռագրերի պահոցն ու շենքը բացահայտում են մշակութային հիշողության ճարտարապետական արտահայտությունը։"],"symbol":["Память Еревана","Երևանի հիշողությունը"],"stage":1,"image":"maps/architecture-map/images/day-1/1-9-matenadaran.jpg"},{"name":["Монумент «Мать Армения»","«Մայր Հայաստան» հուշարձան"],"description":["Монументальный образ народа и одна из высотных доминант города. Остановка завершает этап, посвящённый памяти Еревана.","Հուշարձանն ու շրջակա տարածքը մարմնավորում են պատմական հիշողությունն ու ինքնությունը։"],"symbol":["Память Еревана","Երևանի հիշողությունը"],"stage":1,"image":"maps/architecture-map/images/day-1/1-10-mother.jpg"},{"name":["Спортивно-концертный комплекс имени Карена Демирчяна","Կարեն Դեմիրճյանի անվան մարզահամերգային համալիր"],"description":["Выразительный комплекс со смелым пластическим силуэтом. В программе он открывает разговор о новых формах общественной архитектуры.","Արտահայտիչ ճարտարապետական ձևերը ներկայացնում են հանրային շենքի նոր մոտեցում։"],"symbol":["Город и молодое поколение","Քաղաքը և երիտասարդ սերունդը"],"stage":2,"image":"maps/architecture-map/images/day-1/1-11-sport.jpg"},{"name":["Парк 2800-летия Еревана","Երևանի 2800-ամյակի այգի"],"description":["Городское общественное пространство. На маршруте парк помогает рассмотреть, как планировка и благоустройство формируют среду для отдыха и встреч.","Հանրային այգին ցույց է տալիս, թե ինչպես է քաղաքը ձևավորում միջավայր նոր սերունդների համար։"],"symbol":["Город и молодое поколение","Քաղաքը և երիտասարդ սերունդը"],"stage":2,"image":"maps/architecture-map/images/day-1/1-12-park.jpg"},{"name":["Здание Министерства иностранных дел","Արտաքին գործերի նախարարության շենք"],"description":["Лаконичная геометрия административного здания продолжает разговор о масштабе, функции и выразительности городской архитектуры.","Շենքը ներկայացնում է ժամանակակից պետական ճարտարապետության լեզուն։"],"symbol":["Город и молодое поколение","Քաղաքը և երիտասարդ սերունդը"],"stage":2,"image":"maps/architecture-map/images/day-1/1-13-park.jpg"},{"name":["Поющие фонтаны","Երգող շատրվաններ"],"description":["Финальная остановка на площади Республики. Композиция фонтанов раскрывает идею города как пространства общих впечатлений и событий. Время работы шоу уточняется отдельно.","Լույսը, ջուրն ու երաժշտությունը հրապարակը դարձնում են կենդանի հանդիպման վայր։"],"symbol":["Город и молодое поколение","Քաղաքը և երիտասարդ սերունդը"],"stage":2,"image":"maps/architecture-map/images/day-1/1-14-sing.jpg"}],"path":"maps/architecture-map/day-1.html"},{"folder":"music-day-2","stops":[{"name":["Музей-институт Комитаса","Կոմիտասի թանգարան-ինստիտուտ"],"description":["Знакомство с армянским музыкальным наследием, народными мелодиями и творчеством Комитаса, сыгравшего ключевую роль в сохранении музыкальной традиции Армении.","Ծանոթանում ենք հայկական երաժշտական ժառանգությանը, ժողովրդական մեղեդիներին և Կոմիտասի գործունեությանը։"],"symbol":["Комитас — музыковед и композитор","Կոմիտաս՝ երաժշտագետ և կոմպոզիտոր"],"stage":0,"image":"maps/music-day-2/images/day-2/2-1-komitas.jpg"},{"name":["Ереванская государственная консерватория имени Комитаса","Կոմիտասի անվան Երևանի պետական կոնսերվատորիա"],"description":["Пространство музыкального образования, где академические традиции передаются следующим поколениям и рождаются новые творческие направления. По программе участники попробуют себя в роли студентов консерватории.","Ուսումնասիրում ենք երաժշտական կրթությունն ու կատարողական ժամանակակից փորձը։ Գործնական ծանոթությունը՝ ըստ համաձայնեցված ծրագրի։"],"symbol":["Поколение музыкантов Армении","Հայաստանի երաժիշտների սերունդը"],"stage":1,"image":"maps/music-day-2/images/day-2/2-2-conservatory.jpg"},{"name":["Malkhas Jazz Club","Մալխաս ջազ ակումբ"],"description":["Знакомство с ереванской джазовой сценой и её историей. Здесь маршрут обращается к роли джаза в современной музыкальной культуре города.","Բացահայտում ենք Երևանի ջազային տեսարանը, դրա պատմությունն ու ժամանակակից երաժշտական փորձարկումները։"],"symbol":["Левон Малхасян (Malkhas)","Լևոն Մալխասյան"],"stage":2,"image":"maps/music-day-2/images/day-2/2-3-malkhas.jpg"}],"path":"maps/music-day-2/day-2.html"},{"folder":"kino-day3","stops":[{"name":["Дом-музей Сергея Параджанова","Սերգեյ Փարաջանովի տուն-թանգարան"],"description":["Мемориальный дом-музей режиссёра, открытый в 1991 году, через год после его смерти. В коллекции — коллажи, рисунки, куклы, шляпы, инсталляции и личные вещи мастера. Здесь видно, как визуальный мир Параджанова рождался из самых простых предметов.","Կոլաժները, էսքիզներն ու ինստալյացիաները բացահայտում են ռեժիսորի հեղինակային մոտեցումը, գույնի ու փոխաբերության դերը։"],"symbol":["Символ: Сергей Параджанов — армянский кинорежиссёр","Սերգեյ Փարաջանով՝ կինոռեժիսոր"],"stage":0,"image":"maps/kino-day3/images/day-3/3-1-paraganov.jpg"},{"name":["Показ фильма «Цвет граната»","«Նռան գույնը» ֆիլմի դիտում"],"description":["Фильм Сергея Параджанова 1969 года — поэтическое киноэссе о жизни армянского ашуга Саят-Новы. Вместо привычного сюжета — живые картины из ткани, орнамента и предметов. Просмотр показывает, как культурный код превращается в язык кино.","Ֆիլմի դիտում և քննարկում՝ հայկական մշակույթի խորհրդանիշների, կադրի կառուցվածքի ու պատկերների ռիթմի վերլուծությամբ։"],"symbol":["Символ: фильм Сергея Параджанова","Սերգեյ Փարաջանովի ֆիլմը"],"stage":1,"image":"maps/kino-day3/images/day-3/3-2-granat.jpg"},{"name":["Анимационная студия Саакянца","Սահակյանց անիմացիոն ստուդիա"],"description":["Студия продолжает традиции армянской мультипликации, у истоков которой стоял режиссёр Роберт Саакянц. Её миссия — сохранять наследие армянской анимации и воспитывать новое поколение аниматоров. Участники знакомятся с тем, как рождается анимационный образ: от идеи до персонажа.","Ծանոթանում ենք անիմացիայի ստեղծման փուլերին, էսքիզներին և կադրային պլանավորմանը։"],"symbol":["Символ: Лис — персонаж анимационной студии Саакянца","Աղվես՝ Սահակյանց ստուդիայի կերպար"],"stage":2,"image":"maps/kino-day3/images/day-3/3-3-saakyants.jpg"}],"path":"maps/kino-day3/day-3.html"},{"folder":"Art-day-4","stops":[{"name":["Крепость Эребуни","Էրեբունի ամրոց"],"description":["Урартская крепость на холме Арин-Берд, основанная в 782 году до н. э. царём Аргишти I. Именно с неё принято отсчитывать историю Еревана. Здесь сохранились остатки стен и дворцовых залов, а на территории работает музей с находками раскопок. Древние орнаменты и росписи показывают, откуда начинается визуальный язык армянского искусства.","Ուսումնասիրում ենք հնագույն ձևերը, որմնանկարների հատվածներն ու գեղարվեստական ավանդույթները։ Նախատեսվում է խեցեգործության վարպետաց դաս։"],"symbol":["Символ: Урарту — древнее государство на территории Армении","Ուրարտու"],"stage":0,"image":"maps/Art-day-4/images/day-4/4-1-erebuni.jpg"},{"name":["Национальная галерея Армении","Հայաստանի ազգային պատկերասրահ"],"description":["Главный художественный музей страны на площади Республики. В коллекции представлены армянская и мировая живопись, в том числе работы Мартироса Сарьяна и Ованеса Айвазовского. Знакомство с их полотнами показывает, как армянские мастера работали с цветом, светом и пейзажем.","Սարյանի և Այվազովսկու գործերի օրինակով ուսումնասիրում ենք գույնը, լույսն ու կոմպոզիցիան։ Սքեթչինգը՝ պատկերասրահի համաձայնությամբ։"],"symbol":["Символы: Мартирос Сарьян и Ованес Айвазовский","Մարտիրոս Սարյան և Հովհաննես Այվազովսկի"],"stage":1,"image":"maps/Art-day-4/images/day-4/4-2-galerea.jpg"},{"name":["TUMO Studios","TUMO Studios"],"description":["Образовательная программа TUMO для молодых людей от 18 лет. В ателье учатся создавать современные вещи на основе армянского ремесла и дизайнерских трендов. Здесь прошлое и настоящее превращаются в новые визуальные решения, а участники знакомятся с мировым опытом TUMO.","Ծանոթանում ենք թվային դիզայնին, ստեղծագործական լաբորատորիաներին և միջառարկայական մոտեցմանը։"],"symbol":["Символ: мировой опыт компании TUMO","TUMO-ի ստեղծագործական տեխնոլոգիաների փորձը"],"stage":2,"image":"maps/Art-day-4/images/day-4/4-3-Tumo.jpg"}],"path":"maps/Art-day-4/day-4.html"},{"folder":"Moda-day-5","stops":[{"name":["Музей народного искусства имени Ованеса Шарамбеяна","Հովհաննես Շարամբեյանի անվան ժողովրդական արվեստների թանգարան"],"description":["Музей на улице Абовяна, 64, основанный в 1978 году, хранит около 12 000 предметов армянского декоративно-прикладного искусства: резьбу по дереву, металлу и камню, керамику, кружево, вышивку, ковры и ковровые изделия. Здесь можно увидеть, как ремёсла разных регионов Армении становились основой национальной культуры.","Գորգերը, խեցեղենը, փայտի փորագրությունն ու զարդերը բացահայտում են նյութի և նախշի մեջ պահպանված մշակութային հիշողությունը։"],"symbol":["Символ: Ованес Шарамбеян — армянский художник, основатель музея.","Հովհաննես Շարամբեյան՝ նկարիչ"],"stage":0,"image":"maps/Moda-day-5/images/day-5/5-1-sharambeyan.jpg"},{"name":["«Мегерян Карпет» — фабрика-музей","«Մեգերյան կարպետ» գործարան-թանգարան"],"description":["Действующая фабрика с музеем ковра (улица Мадояна, 9): на экскурсии видно, как ткачи работают за станками, как красят шерсть и как рождается узор. В экспозиции — старинные ковры из семейной коллекции Мегерянов. Ковёр здесь — не только историческое искусство, но и живое современное производство.","Ծանոթանում ենք գորգագործության ավանդական տեխնիկաներին, բնական ներկերին և գորգի ստեղծման ընթացքին։"],"symbol":["Символ: армянский ковёр.","Հայկական գորգ"],"stage":1,"image":"maps/Moda-day-5/images/day-5/5-2-megerian.jpg"},{"name":["Teryan Cultural Center","Տերյան մշակութային կենտրոն"],"description":["Культурный центр на улице Терьяна, 72, известный возрождением армянского национального костюма и традиционной вышивки. На их основе мастера создают новую одежду и аксессуары, соединяя старинные силуэты и орнаменты с современным дизайном. Центр также работает как образовательная площадка, где осваивают традиционные ремёсла.","Ուսումնասիրում ենք ազգային տարազի, նախշերի ու գործվածքների ժամանակակից մեկնաբանությունները հագուստի և աքսեսուարների դիզայնում։"],"symbol":["Символ: армянская одежда и аксессуары.","Հայկական հագուստ և աքսեսուարներ"],"stage":2,"image":"maps/Moda-day-5/images/day-5/5-3-teryan.jpg"}],"path":"maps/Moda-day-5/day-5.html"}];
